<template>
 <dialog ref="dialog" class="bm-seller-preview" aria-labelledby="bm-seller-preview-title" @keydown.tab="trapDialogFocus" @close="closed">
  <header><div><h2 id="bm-seller-preview-title">Xem trước như khách hàng</h2><p>Bản xem riêng từ dữ liệu đã lưu. Sản phẩm chưa duyệt không được công khai.</p></div><button class="button button-outline" type="button" @click="dialog.close()">Đóng</button></header>
  <div class="bm-seller-preview-body"><div class="bm-seller-preview-grid"><CatalogImage :src="usableImage(gallery?.images?.find(i=>i.primary)?.imageUrl||gallery?.imageUrl)" :alt="product.name" fit="contain"/><div><p>{{ category }}</p><h3>{{ product.name }}</h3><strong class="bm-seller-preview-price">{{ money(product.price) }} ₫</strong><p>{{ product.stock }} sản phẩm còn bán</p><p>Trạng thái: {{ productStatusLabels[product.status] }}</p></div></div><section><h3>Mô tả sản phẩm</h3><SellerText :text="content?.description||''" :format="content?.descriptionFormat||'PLAIN'"/></section><section v-if="specs.length"><h3>Thông số đã khai báo</h3><dl><div v-for="item in specs" :key="item.key"><dt>{{ item.label }}</dt><dd>{{ item.value }}</dd></div></dl></section></div>
 </dialog>
</template>
<script setup>
import {computed,onBeforeUnmount,ref} from 'vue';import CatalogImage from '../marketplace/CatalogImage.vue';import SellerText from '../marketplace/SellerText.vue';import {usableImage} from '../../services/catalog.js';import {productStatusLabels} from '../../services/sellerProduct.js';import {lockBodyScroll} from '../../utils/bodyScrollLock.js';import {trapDialogFocus} from '../../utils/dialogFocus.js';
const props=defineProps({product:{type:Object,required:true},content:Object,gallery:Object,category:String}),dialog=ref(null);let opener,unlock;
const money=v=>Number(v||0).toLocaleString('vi-VN',{maximumFractionDigits:2});
const names={scientificName:'Tên khoa học',condition:'Tình trạng',heightCm:'Chiều cao cây (cm)',potDiameterCm:'Đường kính chậu (cm)',potMaterial:'Chất liệu chậu',light:'Ánh sáng',watering:'Tưới nước',substrate:'Giá thể',origin:'Nguồn gốc',careNotes:'Chăm sóc',material:'Chất liệu',shape:'Kiểu dáng',diameterCm:'Đường kính (cm)',lengthCm:'Dài (cm)',widthCm:'Rộng (cm)',color:'Màu sắc',drainageStatus:'Thoát nước',drainageHoleCount:'Số lỗ thoát nước',weightGrams:'Khối lượng (g)',hasTray:'Kèm khay',suitablePlants:'Cây phù hợp',usageInstructions:'Hướng dẫn sử dụng'};
const values={INDIRECT:'Ánh sáng gián tiếp',PARTIAL_SHADE:'Bóng râm một phần',SUN:'Nắng trực tiếp',ROUND:'Tròn',RECTANGULAR:'Chữ nhật',SQUARE:'Vuông',OVAL:'Bầu dục',OTHER:'Khác',YES:'Có',NO:'Không',UNKNOWN:'Chưa rõ'};
const specs=computed(()=>[
 ...Object.entries(props.content?.specifications||{}).filter(([k])=>!props.content?.potSpecs||!['potMaterial','potDiameterCm'].includes(k)).map(([k,v])=>({key:'general-'+k,label:names[k],value:v})),
 ...Object.entries(props.content?.potSpecs||{}).map(([k,v])=>({key:'pot-'+k,label:k==='heightCm'?'Chiều cao chậu (cm)':names[k],value:v})),
].filter(i=>i.label&&i.value!==null&&i.value!==undefined&&i.value!=='').map(i=>({...i,value:typeof i.value==='boolean'?(i.value?'Có':'Không'):values[i.value]||i.value})));
function open(trigger){opener=trigger;unlock=lockBodyScroll();dialog.value.showModal();}function closed(){unlock?.();unlock=undefined;opener?.focus({preventScroll:true});}onBeforeUnmount(()=>unlock?.());defineExpose({open});
</script>
<style scoped>
.bm-seller-preview{width:min(960px,calc(100% - 24px));max-height:calc(100dvh - 32px);padding:0;border:1px solid var(--bm-border);border-radius:var(--bm-radius);color:var(--bm-ink);background:var(--bm-surface);overflow:hidden}.bm-seller-preview[open]{display:grid;grid-template-rows:auto minmax(0,1fr)}.bm-seller-preview::backdrop{background:var(--bm-scrim)}header{display:flex;justify-content:space-between;align-items:start;gap:24px;padding:20px 24px;border-bottom:1px solid var(--bm-border)}header h2{margin:0;font-size:20px}header p{max-width:65ch;margin:8px 0 0;color:var(--bm-muted)}header button{flex-shrink:0}.bm-seller-preview-body{overflow:auto;padding:24px;overscroll-behavior:contain}.bm-seller-preview-grid{display:grid;grid-template-columns:1fr 1fr;gap:32px;align-items:center}.bm-seller-preview-price{font-size:24px;color:var(--bm-forest)}section{margin-top:32px}dl>div{display:grid;grid-template-columns:1fr 2fr;gap:16px;padding:12px 0;border-bottom:1px solid var(--bm-border)}dd{margin:0;overflow-wrap:anywhere}button:focus-visible{outline:3px solid var(--bm-focus);outline-offset:3px}@media(max-width:600px){.bm-seller-preview-grid{grid-template-columns:1fr}header,.bm-seller-preview-body{padding:16px}header{gap:12px;flex-wrap:wrap}dl>div{grid-template-columns:1fr}}
</style>
